rules.logic:
// Find the "More from YouTube" section by its title text
const allSections = element.querySelectorAll('ytd-guide-section-renderer');
let moreFromYT = null;
for (const section of allSections) {
  const titleEl = section.querySelector('#guide-section-title');
  if (titleEl && titleEl.textContent.trim() === 'More from YouTube') {
    moreFromYT = section;
    break;
  }
}
// Only move it if found and it's not already the first child
if (moreFromYT && element.firstElementChild !== moreFromYT) {
  element.insertBefore(moreFromYT, element.firstElementChild);
}
